-- Row-level security for the runtime role on every table: rows of organizations registered
-- for the current login, narrowed to app.organization_id when a transaction pins it.
ALTER TABLE "identity_private"."ai_proposals" ENABLE ROW LEVEL SECURITY; ALTER TABLE "identity_private"."ai_proposals" FORCE ROW LEVEL SECURITY;
CREATE POLICY noxh_app_scope ON "identity_private"."ai_proposals" TO noxh_app USING (organization_id IN (SELECT i.organization_id FROM identity_private.instance_organizations i WHERE i.runtime_role = CURRENT_USER) AND (NULLIF(pg_catalog.current_setting('app.organization_id', true), '') IS NULL OR organization_id = NULLIF(pg_catalog.current_setting('app.organization_id', true), '')::pg_catalog.uuid)) WITH CHECK (organization_id IN (SELECT i.organization_id FROM identity_private.instance_organizations i WHERE i.runtime_role = CURRENT_USER) AND (NULLIF(pg_catalog.current_setting('app.organization_id', true), '') IS NULL OR organization_id = NULLIF(pg_catalog.current_setting('app.organization_id', true), '')::pg_catalog.uuid));
